"""Ilustrações v2 do tour (11 etapas): personagem sem rosto + cena grande, cores por variável --q-*. viewBox 360x240, sem texto, sem imagem, sem filtro."""
from base import *
def chao(): return f'<ellipse cx="180" cy="214" rx="120" ry="10" fill="{V("superficie-2")}"/>'
def fundo(c1="primaria-suave", c2="secundaria-suave"):
    return mancha(180, 124, 140, 96, c1) + f'<circle cx="300" cy="52" r="30" fill="{V(c2)}"/><circle cx="56" cy="196" r="18" fill="{V(c2)}"/>' + brilho(62, 52, 10) + brilho(318, 150, 7) + brilho(40, 110, 5, "primaria")
def alvo(cx, cy, r):
    return (f'<circle cx="{cx}" cy="{cy}" r="{r}" fill="{V("superficie")}" stroke="{V("primaria")}" stroke-width="6"/><circle cx="{cx}" cy="{cy}" r="{r*.62:.0f}" fill="{V("primaria")}"/>'
            f'<circle cx="{cx}" cy="{cy}" r="{r*.3:.0f}" fill="{V("superficie")}"/><path d="M{cx} {cy}L{cx+r+18} {cy-r-18}" stroke="{V("texto")}" stroke-width="5" stroke-linecap="round"/>'
            f'<path d="M{cx+r+8} {cy-r-26}l14 0l0 14z" fill="{V("energia")}" stroke="{V("texto")}" stroke-width="3" stroke-linejoin="round"/>')
def relogio(cx, cy, r):
    return (f'<rect x="{cx-7}" y="{cy-r-16}" width="14" height="12" rx="3" fill="{V("texto")}"/><circle cx="{cx}" cy="{cy}" r="{r}" fill="{V("superficie")}" stroke="{V("texto")}" stroke-width="6"/>'
            f'<path d="M{cx} {cy}L{cx} {cy-r}A{r} {r} 0 0 1 {cx+r*.87:.1f} {cy+r*.5:.1f}Z" fill="{V("primaria")}"/><circle cx="{cx}" cy="{cy}" r="5" fill="{V("texto")}"/>')
def cal(x, y):
    s = f'<rect x="{x}" y="{y}" width="116" height="104" rx="14" fill="{V("superficie")}" stroke="{V("texto")}" stroke-width="4"/><rect x="{x}" y="{y}" width="116" height="26" rx="12" fill="{V("primaria")}"/>'
    for i in range(7):
        cx, cy = x+18+(i % 4)*27, y+46+(i//4)*32
        s += (f'<circle cx="{cx}" cy="{cy}" r="10" fill="{V("primaria")}"/><path d="M{cx-5} {cy}l4 4l7-8" stroke="{V("superficie")}" stroke-width="3" fill="none" stroke-linecap="round" stroke-linejoin="round"/>'
              if i in (0, 2, 4) else f'<circle cx="{cx}" cy="{cy}" r="10" fill="{V("superficie-2")}" stroke="{V("texto-suave")}" stroke-width="2"/>')
    return s
CENAS = {
 "objetivo": ("Pessoa com o punho erguido ao lado de um alvo acertado", lambda: fundo() + chao() + alvo(248, 110, 46) + pessoa(130, 212, 1.25, "punho", 2, 0, "primaria")),
 "nivel": ("Pessoa comemorando no topo de três degraus que sobem", lambda: fundo() + chao() + "".join(f'<rect x="{170+i*44}" y="{170-i*36}" width="40" height="{44+i*36}" rx="8" fill="{V(["secundaria-suave","secundaria","primaria"][i])}" stroke="{V("texto")}" stroke-width="3"/>' for i in range(3)) + pessoa(278, 98, 0.62, "vitoria", 0, 1, "primaria", coque=True) + pessoa(110, 212, 1.15, "apontar", 4, 3, "secundaria")),
 "dias": ("Pessoa apontando para um calendário com dias marcados", lambda: fundo() + chao() + cal(190, 70) + pessoa(120, 212, 1.25, "apontar", 1, 2, "primaria", coque=True)),
 "tempo": ("Pessoa correndo ao lado de um cronômetro", lambda: fundo("secundaria-suave", "primaria-suave") + chao() + relogio(250, 112, 50) + pessoa(120, 208, 1.2, "correr", 3, 0, "primaria") + f'<path d="M40 150h30M30 170h34M48 130h22" stroke="{V("texto-suave")}" stroke-width="5" stroke-linecap="round"/>'),
 "onde-treina": ("Pessoa levantando halteres entre uma casa e uma academia", lambda: fundo() + chao() + f'<path d="M226 120l40-32l40 32v70h-80z" fill="{V("superficie")}" stroke="{V("texto")}" stroke-width="4" stroke-linejoin="round"/><rect x="254" y="150" width="24" height="40" rx="4" fill="{V("primaria")}"/>' + f'<rect x="30" y="112" width="62" height="80" rx="8" fill="{V("secundaria")}" stroke="{V("texto")}" stroke-width="4"/>' + halter(61, 140, 1.1, "superficie") + pessoa(160, 212, 1.2, "halter", 5, 1, "primaria", mao_d=lambda x, y: halter(x, y, 1.1), mao_e=lambda x, y: halter(x, y, 1.1))),
 "areas-do-corpo": ("Pessoa flexionando os braços com os bíceps em destaque", lambda: fundo() + chao() + pessoa(180, 212, 1.35, "flexionar", 2, 3, "primaria") + f'<circle cx="122" cy="112" r="16" fill="none" stroke="{V("energia")}" stroke-width="5"/><circle cx="238" cy="112" r="16" fill="none" stroke="{V("energia")}" stroke-width="5"/>' + brilho(100, 84, 9) + brilho(262, 84, 9)),
 "altura-e-peso": ("Pessoa em pé sobre uma balança ao lado de uma régua de altura", lambda: fundo() + chao() + f'<rect x="210" y="40" width="30" height="172" rx="8" fill="{V("superficie")}" stroke="{V("texto")}" stroke-width="4"/>' + "".join(f'<path d="M210 {56+i*18}h{14 if i%2 else 22}" stroke="{V("texto")}" stroke-width="3"/>' for i in range(9)) + f'<rect x="110" y="200" width="72" height="14" rx="7" fill="{V("secundaria")}" stroke="{V("texto")}" stroke-width="3"/>' + pessoa(146, 200, 1.2, "em-pe", 4, 0, "primaria", coque=True) + f'<path d="M262 50l12-12l12 12M274 38v40" stroke="{V("primaria")}" stroke-width="5" fill="none" stroke-linecap="round" stroke-linejoin="round"/>'),
 "lesoes": ("Pessoa alongando o corpo ao lado de um escudo com sinal de cuidado", lambda: fundo("secundaria-suave", "primaria-suave") + chao() + f'<path d="M252 62l44 16v38c0 30-20 50-44 60c-24-10-44-30-44-60v-38z" fill="{V("superficie")}" stroke="{V("texto")}" stroke-width="4" stroke-linejoin="round"/><path d="M252 96v44M230 118h44" stroke="{V("sucesso")}" stroke-width="10" stroke-linecap="round"/>' + pessoa(130, 212, 1.25, "alongar", 1, 2, "secundaria")),
 "preferencia-alimentar": ("Pessoa segurando uma tigela ao lado de um prato com folhas e frutas", lambda: fundo() + chao() + f'<circle cx="252" cy="126" r="56" fill="{V("superficie")}" stroke="{V("texto")}" stroke-width="4"/><circle cx="252" cy="126" r="38" fill="{V("superficie-2")}"/><path d="M232 130c10-24 30-24 40-10c-12 18-28 20-40 10z" fill="var(--q-folha)"/><circle cx="262" cy="108" r="10" fill="{V("primaria")}"/><circle cx="238" cy="112" r="7" fill="{V("energia")}"/>' + pessoa(120, 212, 1.25, "beber", 3, 1, "primaria", coque=True, mao_d=lambda x, y: f'<path d="M{x-16:.0f} {y-6:.0f}h32a16 14 0 0 1-32 0z" fill="{V("secundaria")}" stroke="{V("texto")}" stroke-width="3"/>')),
 "lembretes": ("Pessoa acenando ao lado de um sino de notificação", lambda: fundo() + chao() + f'<path d="M218 168v-46a38 38 0 0 1 76 0v46l12 14h-100z" fill="{V("energia")}" stroke="{V("texto")}" stroke-width="4" stroke-linejoin="round"/><circle cx="256" cy="190" r="10" fill="{V("texto")}"/><circle cx="292" cy="86" r="14" fill="{V("primaria")}" stroke="{V("superficie")}" stroke-width="4"/><path d="M196 96q-10 16 0 32M316 96q10 16 0 32" stroke="{V("texto-suave")}" stroke-width="4" fill="none" stroke-linecap="round"/>' + pessoa(120, 212, 1.25, "acenar", 0, 3, "secundaria")),
 "cidade-e-bairro": ("Pessoa correndo por uma rua até um marcador de mapa", lambda: fundo("secundaria-suave", "primaria-suave") + chao() + f'<path d="M30 200C110 150 180 210 330 140" stroke="{V("superficie")}" stroke-width="22" fill="none" stroke-linecap="round"/><path d="M30 200C110 150 180 210 330 140" stroke="{V("texto-suave")}" stroke-width="3" stroke-dasharray="10 10" fill="none"/><path d="M270 120c-22-24-30-38-30-52a30 30 0 0 1 60 0c0 14-8 28-30 52z" fill="{V("primaria")}" stroke="{V("texto")}" stroke-width="4"/><circle cx="270" cy="68" r="11" fill="{V("superficie")}"/>' + pessoa(130, 204, 1.2, "correr", 2, 0, "primaria", coque=True)),
}
ORDEM = ["objetivo","nivel","dias","tempo","onde-treina","areas-do-corpo","altura-e-peso","lesoes","preferencia-alimentar","lembretes","cidade-e-bairro"]
def ilustracao(k, idd=None): d, f = CENAS[k]; return svg_doc((360, 240), d, f(), idd or f"ilu-{k}")
